        while (!Talked()) { NSF(); if (T()) return; }
        if (T()) return;
        Speak("ALTERNATIVE");
        Log("ask");
        long answer;
        while ((answer = Frame >= AnswerAt ? Answer : -1) < 0) { NSF(); if (T()) return; }
        if (T()) return;
        if (answer == 1) { if (T()) return; Speak("ACCEPTED"); Log("marry"); MissionFailed = true; }
        Log("clear");
    }
};
